<div class="patient-page-heading"><div><span class="eyebrow text-secondary">CONTROL Y TRAZABILIDAD</span><h1><?= $escape($title) ?></h1><p class="text-secondary mb-0">Operaciones registradas por el esquema real</p></div><span class="status-chip is-active">Solo consulta</span></div>
<form method="get" action="/auditoria" class="schedule-filters">
<div><label class="form-label" for="usuario">Usuario responsable</label><select class="form-select" id="usuario" name="usuario"><option value="">Todos</option><?php foreach($data['users'] as $account): ?><option value="<?= $escape($account['id_usuario']) ?>" <?= $filters['usuario']===(int)$account['id_usuario']?'selected':'' ?>><?= $escape($account['nombre_usuario'].' · '.$account['rol']) ?></option><?php endforeach; ?></select></div>
<div><label class="form-label" for="fecha_inicio">Fecha inicial</label><input class="form-control" id="fecha_inicio" name="fecha_inicio" type="date" value="<?= $escape($filters['fecha_inicio']) ?>"></div>
<div><label class="form-label" for="fecha_fin">Fecha final</label><input class="form-control" id="fecha_fin" name="fecha_fin" type="date" value="<?= $escape($filters['fecha_fin']) ?>"></div>
<div><label class="form-label" for="operacion">Operación</label><select class="form-select" id="operacion" name="operacion"><option value="">Todas</option><?php foreach(\Clinica\Services\AuditFilters::OPERATIONS as $operation): ?><option value="<?= $escape($operation) ?>" <?= $filters['operacion']===$operation?'selected':'' ?>><?= $escape($operation) ?></option><?php endforeach; ?></select></div>
<div><label class="form-label" for="entidad">Entidad afectada</label><input class="form-control" id="entidad" name="entidad" maxlength="80" value="<?= $escape($filters['entidad']) ?>" placeholder="Ej. citas"></div>
<button class="btn btn-clinic" type="submit">Aplicar filtros</button><a class="btn btn-outline-secondary" href="/auditoria">Limpiar</a>
</form>
<section class="patient-card mb-4"><div class="schedule-card-heading"><strong>Movimientos registrados</strong><span><?= $escape($data['total']) ?> resultados · página <?= $escape($filters['pagina']) ?>/<?= $escape($data['pages']) ?></span></div>
<?php if(!$data['rows']): ?><div class="patient-empty"><h2 class="h5">No hay movimientos para mostrar</h2><p class="text-secondary mb-0">No existen registros de auditoría con los filtros aplicados.</p></div>
<?php else: ?><div class="table-responsive"><table class="table patient-table mb-0"><thead><tr><th>Fecha y hora</th><th>Actor</th><th>Operación</th><th>Entidad</th><th>Registro</th><th></th></tr></thead><tbody><?php foreach($data['rows'] as $row): ?><tr><td><?= $escape($row['fecha_hora']) ?></td><td><?= $escape($row['nombre_usuario'] ?? 'Actor no registrado') ?></td><td><?= $escape($row['operacion']) ?></td><td><?= $escape($row['entidad_afectada']) ?></td><td><?= $escape($row['id_entidad']) ?></td><td><a href="/auditoria/detalle?id=<?= $escape($row['id_registro']) ?>">Ver detalle</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php if($data['pages']>1): ?><nav class="mt-3" aria-label="Paginación de auditoría"><ul class="pagination mb-0"><?php for($page=1;$page<=$data['pages'];$page++): ?><li class="page-item <?= $page===$filters['pagina']?'active':'' ?>"><a class="page-link" href="<?= $escape($pageLink($page)) ?>"><?= $page ?></a></li><?php endfor; ?></ul></nav><?php endif; ?></section>
<section class="patient-card"><div class="schedule-card-heading"><strong>Historial de cambios de citas</strong><span><?= count($data['history']) ?> resultados recientes</span></div>
<?php if(!$data['history']): ?><div class="patient-empty"><h2 class="h5">No hay cambios de citas registrados</h2><p class="text-secondary mb-0">La tabla de historial no contiene movimientos para los filtros aplicados.</p></div>
<?php else: ?><div class="table-responsive"><table class="table patient-table mb-0"><thead><tr><th>Fecha y hora</th><th>Cita</th><th>Actor</th><th>Tipo</th><th>Antes</th><th>Después</th></tr></thead><tbody><?php foreach($data['history'] as $row): ?><tr><td><?= $escape($row['fecha_hora_cambio']) ?></td><td><?= $escape($row['id_cita']) ?></td><td><?= $escape($row['nombre_usuario'] ?? 'Actor no registrado') ?></td><td><?= $escape($row['tipo_cambio']) ?></td><td><?= $escape(($row['fecha_anterior'] ?? '').' '.($row['hora_inicio_anterior'] ?? '').' · '.($row['estado_anterior'] ?? '')) ?></td><td><?= $escape(($row['fecha_nueva'] ?? '').' '.($row['hora_inicio_nueva'] ?? '').' · '.($row['estado_nuevo'] ?? '')) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
